#include <sprods_com_mod.hpp>
#include <FArray.hpp>
#include <Need.hpp>

// Amplitudes for 0 -> qb- q+ g+ g- g+ from:
// 'One-Loop Corrections to Two-Quark Three-Gluon Amplitudes'
//  Zvi Bern, Lance Dixon, David A. Kosower
// Published in: Nucl.Phys.B 437 (1995) 259-304,
// e-Print: hep-ph/9409393 [hep-ph]

using namespace constants_mod;
using namespace mxpart_mod;
using namespace epinv_mod;
using namespace epinv2_mod;
using namespace scale_mod;
using namespace sprods_com_mod;

void A5qbmqpgpgmgp(int j1, int j2, int j3, int j4, int j5, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb, std::complex<double>& miA5tree, std::complex<double>& AL, std::complex<double>& ASUSY, std::complex<double>& Af, std::complex<double>& As) {

  std::complex<double> VSUSY, VL, Vggluon, Vg12;
  std::complex<double> FSUSY, FS, FL, Ffgluon, Ff;

  // Eq. (5.15)
  miA5tree = std::pow(za(j1,j4),3)*za(j2,j4)/(za(j1,j2)*za(j2,j3)*za(j3,j4)*za(j4,j5)*za(j5,j1));

  Vggluon = -five*epinv*epinv2
    - epinv*(lnrat(musq,-s(j1,j2))+lnrat(musq,-s(j2,j3))+lnrat(musq,-s(j3,j4))
            +lnrat(musq,-s(j4,j5))+lnrat(musq,-s(j5,j1)))
    - half*(std::pow(lnrat(musq,-s(j1,j2)),2)+std::pow(lnrat(musq,-s(j2,j3)),2)+std::pow(lnrat(musq,-s(j3,j4)),2)
            +std::pow(lnrat(musq,-s(j4,j5)),2)+std::pow(lnrat(musq,-s(j5,j1)),2))
    + lnrat(-s(j1,j2),-s(j2,j3))*lnrat(-s(j3,j4),-s(j4,j5))
    + lnrat(-s(j2,j3),-s(j3,j4))*lnrat(-s(j4,j5),-s(j5,j1))
    + lnrat(-s(j3,j4),-s(j4,j5))*lnrat(-s(j5,j1),-s(j1,j2))
    + lnrat(-s(j4,j5),-s(j5,j1))*lnrat(-s(j1,j2),-s(j2,j3))
    + lnrat(-s(j5,j1),-s(j1,j2))*lnrat(-s(j2,j3),-s(j3,j4))
    + five/six*pisq;
  Vg12 = Vggluon+epinv*epinv2+epinv*lnrat(musq,-s(j1,j2))+half*std::pow(lnrat(musq,-s(j1,j2)),2);

  VSUSY = Vggluon-3.0*epinv-1.5*(lnrat(musq,-s(j1,j2))+lnrat(musq,-s(j3,j4)))-6.0;
  VL = Vg12-1.5*(epinv+lnrat(musq,-s(j3,j4)))-2.0;

  // Eq. (5.16)
  FSUSY =
    -3.0*za(j1,j3)*za(j1,j4)*za(j2,j4)*std::pow(zb(j3,j5),2)/(za(j1,j2)*za(j2,j3))
      *Ls1(-s(j3,j4),-s(j1,j2),-s(j4,j5),-s(j1,j2))/std::pow(s(j1,j2),2)
    -3.0*za(j1,j4)*std::pow(za(j2,j4),2)*std::pow(zb(j2,j5),2)/(za(j2,j3)*za(j3,j4))
      *Ls1(-s(j5,j1),-s(j3,j4),-s(j1,j2),-s(j3,j4))/std::pow(s(j3,j4),2)
    -1.5*std::pow(za(j1,j4),2)*za(j2,j4)/(za(j1,j2)*za(j2,j3)*za(j3,j4)*za(j4,j5)*za(j5,j1))
      *(za(j1,j2)*zb(j2,j5)*za(j5,j4)+za(j1,j5)*zb(j5,j3)*za(j3,j4))
      *L0(-s(j1,j2),-s(j3,j4))/s(j3,j4);

  Ffgluon = FSUSY*za(j4,j1)/(3.0*za(j4,j2));

  FS = 2.0*za(j1,j3)*za(j3,j4)*za(j4,j5)*za(j1,j5)*std::pow(zb(j3,j5),4)/za(j1,j2)
      *Ls3(-s(j3,j4),-s(j1,j2),-s(j4,j5),-s(j1,j2))/std::pow(s(j1,j2),4)
    +2.0/3.0*za(j1,j4)*za(j1,j5)*za(j3,j4)*std::pow(zb(j3,j5),3)/za(j1,j2)
      *L2(-s(j1,j2),-s(j3,j4))/std::pow(s(j3,j4),3)
    +2.0/3.0*za(j1,j3)*za(j1,j4)*za(j4,j5)*std::pow(zb(j3,j5),3)/za(j1,j2)
      *L2(-s(j1,j2),-s(j4,j5))/std::pow(s(j4,j5),3)
    -1.0/3.0*za(j1,j3)*za(j1,j5)*std::pow(zb(j3,j5),4)/(za(j1,j2)*zb(j3,j4)*zb(j4,j5)*std::pow(s(j1,j2),2));

  FL = FS
    -za(j1,j3)*za(j3,j4)*za(j4,j5)*std::pow(zb(j3,j5),3)/za(j2,j3)
      *Ls2(-s(j3,j4),-s(j1,j2),-s(j4,j5),-s(j1,j2))/std::pow(s(j1,j2),3)
    -za(j1,j2)*std::pow(za(j2,j4),2)*za(j4,j5)*std::pow(zb(j2,j5),3)/(za(j2,j3)*za(j3,j4))
      *Ls2(-s(j5,j1),-s(j3,j4),-s(j1,j2),-s(j3,j4))/std::pow(s(j3,j4),3)
    +za(j1,j4)*std::pow(zb(j3,j5),2)*(za(j1,j4)*za(j2,j3)*za(j1,j5)
      +2.0*za(j1,j3)*za(j1,j5)*za(j2,j4)+za(j1,j3)*za(j1,j4)*za(j2,j5))/(za(j1,j2)*za(j2,j3)*za(j5,j1))
      *Ls1(-s(j3,j4),-s(j1,j2),-s(j4,j5),-s(j1,j2))/std::pow(s(j1,j2),2)
    +za(j1,j4)*za(j2,j4)*std::pow(zb(j2,j5),2)*(2.0*za(j1,j5)*za(j2,j4)+za(j1,j4)*za(j2,j5))
      /(za(j2,j3)*za(j3,j4)*za(j5,j1))
      *Ls1(-s(j5,j1),-s(j3,j4),-s(j1,j2),-s(j3,j4))/std::pow(s(j3,j4),2)
    +std::pow(za(j1,j4),3)*za(j1,j3)*std::pow(zb(j1,j3),2)/(za(j2,j3)*za(j4,j5)*za(j5,j1))
      *Ls1(-s(j1,j2),-s(j4,j5),-s(j2,j3),-s(j4,j5))/std::pow(s(j4,j5),2)
    -1.5*std::pow(za(j1,j4),2)*za(j2,j4)/(za(j1,j2)*za(j2,j3)*za(j3,j4)*za(j4,j5)*za(j5,j1))
      *(za(j1,j2)*zb(j2,j5)*za(j5,j4)+za(j1,j5)*zb(j5,j3)*za(j3,j4))
      *L0(-s(j1,j2),-s(j3,j4))/s(j3,j4)
    -std::pow(za(j1,j4),2)*zb(j3,j5)/(za(j2,j3)*za(j1,j5))
      *L0(-s(j1,j2),-s(j3,j4))/s(j3,j4)
    +std::pow(za(j1,j4),2)*za(j2,j4)*zb(j2,j3)/(za(j4,j5)*za(j1,j5)*za(j2,j3))
      *L0(-s(j1,j2),-s(j4,j5))/s(j4,j5)
    -std::pow(za(j1,j4),3)*zb(j1,j3)/(za(j2,j3)*za(j4,j5)*za(j1,j5))
      *L0(-s(j2,j3),-s(j4,j5))/s(j4,j5)
    -std::pow(za(j1,j4),2)*za(j2,j4)*zb(j2,j5)/(za(j2,j3)*za(j3,j4)*za(j1,j5))
      *L0(-s(j3,j4),-s(j5,j1))/s(j5,j1)
    +0.5*(za(j1,j4)*za(j3,j4)*std::pow(zb(j3,j5),2)/za(j2,j3)
        *L1(-s(j1,j2),-s(j3,j4))/std::pow(s(j3,j4),2)
      +za(j1,j2)*za(j1,j4)*za(j2,j4)*za(j4,j5)*std::pow(zb(j2,j5),2)/(za(j2,j3)*za(j3,j4)*za(j1,j5))
        *L1(-s(j3,j4),-s(j1,j2))/std::pow(s(j1,j2),2)
      +za(j1,j4)*std::pow(za(j2,j4),2)*std::pow(zb(j2,j5),2)/(za(j2,j3)*za(j3,j4))
        *L1(-s(j3,j4),-s(j5,j1))/std::pow(s(j5,j1),2)
      +za(j2,j4)*std::pow(zb(j2,j5),2)*zb(j3,j5)/(zb(j1,j2)*za(j2,j3)*s(j3,j4)*zb(j4,j5))
      +za(j1,j3)*za(j1,j4)*zb(j1,j5)*std::pow(zb(j3,j5),2)/(s(j1,j2)*za(j2,j3)*s(j3,j4)*zb(j4,j5))
      +za(j1,j4)*std::pow(za(j2,j4),2)*std::pow(zb(j2,j5),2)/(za(j2,j3)*za(j3,j4)*s(j3,j4)*s(j5,j1))
      -std::pow(za(j1,j4),2)*za(j2,j4)*zb(j2,j3)/(s(j1,j2)*za(j2,j3)*za(j4,j5)*za(j1,j5)));

  Ff = -std::pow(za(j1,j4),2)*std::pow(zb(j3,j5),2)/za(j1,j2)
    *Ls1(-s(j3,j4),-s(j1,j2),-s(j4,j5),-s(j1,j2))/std::pow(s(j1,j2),2);

  AL = VL*miA5tree+FL; // @coverage-probe
  ASUSY = VSUSY*miA5tree+FSUSY;
  // Vs = Vf =0, per Eq. (5.10)
  Af = Ff;
  As = FS;

  return;
}

extern "C" {
  void A5qbmqpgpgmgp_wrapper(int j1, int j2, int j3, int j4, int j5, std::complex<double>* fza, std::complex<double>* fzb, std::complex<double>& miA5tree, std::complex<double>& AL, std::complex<double>& ASUSY, std::complex<double>& Af, std::complex<double>& As) {

    FArray2D<std::complex<double>> za(fza, mxpart, mxpart);
    FArray2D<std::complex<double>> zb(fzb, mxpart, mxpart);
    A5qbmqpgpgmgp(j1, j2, j3, j4, j5, za, zb, miA5tree, AL, ASUSY, Af, As);
  }
}
